// Generated by `just generate` from `src/plugins/claudetto/slices/policy/lab/world.ts`. Edit the source and run `just generate`.
// The shared world of the lab tests of the `policy` slice: stubs of `git`, `gh`, and the disk, and the calls of a tool.
// The stubs of `process.run` and of `fs.*` stand for `git`, `gh`, and the disk, so no process runs and no file is written.
// `just generate` copies this file next to the lab tests in `tests/` of the plugin.

import type { On, PluginOptions } from "claude-code";
import type { Engine } from "claude-code/testing";

declare module "claude-code" {
  interface McpToolInputs {
    mcp__github__create_pull_request: { owner: string; repo: string };
    mcp__claudetto__ai_policy: {
      repo: string;
      verdict: string;
      quote?: string;
      conditions?: string;
      read: string[];
    };
  }
}

export const LOGIN = "me";

/** The endpoint of the organizations of the user, as the slice calls it. */
export const ORGS_PATH = "user/memberships/orgs?state=active";

/** The world of one test: the files on the fake disk, and the checkout of each folder. */
export type World = {
  files: Record<string, string>;
  /** Folder -> `[root, origin url]`. A folder that is not here is in no repository. */
  repos: Record<string, [string, string]>;
  /** The session folder. The first checkout is the default. */
  cwd?: string;
  /** The session folder is not readable: the stub of `session.cwd` throws, as an engine fault does. */
  failCwd?: boolean;
  /** The 1-based numbers of the `session.cwd` calls that throw. Another hook of the engine can call it too. */
  failCwdCalls?: number[];
  /** Remote name -> URL, for `git remote get-url`. `origin` is the URL of the checkout. */
  remotes?: Record<string, string>;
  /** `OWNER/NAME` of a fork -> `OWNER/NAME` of its parent. */
  parents?: Record<string, string>;
  /** The env vars of the process past `HOME`. `$.env.set` changes them. */
  env?: Record<string, string>;
  /** The output of `gh api user/memberships/orgs`. With no value, the call fails. */
  orgs?: string;
  /** Gets a copy of the env vars each time a built-in tool runs. */
  seen?: Record<string, string>[];
  /** Gets the `env` of each `gh api` call of the slice. */
  ghEnv?: (Record<string, string> | undefined)[];
  /** Runs while a built-in tool runs, so that a test can start a second call in the window of the first. */
  during?: () => Promise<void>;
};

const DONE = {
  isStdoutTruncated: false,
  isStderrTruncated: false,
} as const;

const entry = (name: string, kind: "file" | "dir") => ({
  name,
  kind,
  size: 0,
  mtimeMs: 0,
  isLink: false,
});

/** Stubs for one test. Gives the fake disk, so that a test can read what the hook wrote. */
export const stub = (on: On, world: World): Record<string, string> => {
  const disk = world.files;
  const vars: Record<string, string> = { HOME: "/home/me", ...world.env };
  on("env.get", (_$, e) => ({ value: vars[e.name] }));
  on("env.set", (_$, e) => {
    if (e.value === undefined) delete vars[e.name];
    else vars[e.name] = e.value;
    return { value: {} };
  });
  on("session.id", () => ({ value: `s-${Object.keys(disk).join("|")}` }));
  let cwdCalls = 0;
  on("session.cwd", () => {
    cwdCalls += 1;
    if (world.failCwd || world.failCwdCalls?.includes(cwdCalls))
      throw new Error("the engine failed");
    return {
      value: world.cwd ?? Object.keys(world.repos)[0] ?? "/tmp",
    };
  });
  on("clock.now", () => ({ value: 1_000_000 }));
  on("fs.exists", (_$, e) => ({
    value:
      e.path in disk ||
      Object.keys(disk).some((k) => k.startsWith(`${e.path}/`)),
  }));
  on("fs.read", (_$, e) => ({ value: disk[e.path] ?? "" }));
  on("fs.write", (_$, e) => {
    disk[e.path] = e.text;
    return { value: undefined };
  });
  on("fs.list", (_$, e) => {
    const prefix = `${e.path}/`;
    const names = new Map<string, "file" | "dir">();
    for (const k of Object.keys(disk)) {
      if (!k.startsWith(prefix)) continue;
      const rest = k.slice(prefix.length);
      const slash = rest.indexOf("/");
      names.set(
        slash < 0 ? rest : rest.slice(0, slash),
        slash < 0 ? "file" : "dir",
      );
    }
    return { value: [...names].map(([n, kind]) => entry(n, kind)) };
  });
  on("process.run", (_$, e) => {
    const [a, b, c, d] = e.argv;
    const out = (stdout: string, exitCode = 0, stderr = "") => ({
      value: { exitCode, stdout, stderr, ...DONE },
    });
    if (a === "gh" && b === "config") return out(`${LOGIN}\n`);
    if (a === "git" && b === "-C" && c !== undefined) {
      const repo = Object.values(world.repos).find(
        (r) => c === r[0] || c.startsWith(`${r[0]}/`),
      );
      if (repo === undefined) return out("", 128, "not a git repository");
      if (d === "rev-parse") return out(`${repo[0]}\n`);
      if (d === "branch") return out("main\n");
      if (d === "config") return out("", 1);
      const name = e.argv.at(-1) ?? "";
      const url = world.remotes?.[name] ?? (name === "origin" ? repo[1] : "");
      return url === "" ? out("", 2, "no such remote") : out(`${url}\n`);
    }
    if (a === "gh" && b === "repo") {
      const parent = world.parents?.[d ?? ""]?.split("/");
      return out(
        parent === undefined
          ? '{"parent":null}'
          : JSON.stringify({
              parent: { name: parent[1], owner: { login: parent[0] } },
            }),
      );
    }
    if (a === "gh" && b === "api" && e.argv.includes(ORGS_PATH)) {
      world.ghEnv?.push(e.init?.env);
      return world.orgs === undefined
        ? out("", 1, "HTTP 401: Bad credentials")
        : out(world.orgs);
    }
    if (a === "gh" && b === "api") return out("", 1, "HTTP 404: Not Found");
    return out("");
  });
  // The built-in tools answer `ok`, and the tool of the slice goes to its own handler.
  on("tool.call", async (_$, e, next) => {
    if (e.tool === "mcp__claudetto__ai_policy") return next(e);
    world.seen?.push({ ...vars });
    await world.during?.();
    return { result: "ok" };
  });
  return disk;
};

export const option = (aiPolicy?: boolean): { options: PluginOptions } => ({
  options: aiPolicy === undefined ? {} : { aiPolicy },
});

export const denyOf = (out: object): string | undefined =>
  "deny" in out ? String(out.deny) : undefined;

export const write = ($: Engine, dir: string) =>
  $.tool.call({
    tool: "Write",
    file_path: `${dir}/src/a.ts`,
    content: "x",
  });

/** A `git push` in `dir`, which is the first action that the gate checks. */
export const push = ($: Engine, dir: string, args = "") =>
  $.tool.call({ tool: "Bash", command: `cd ${dir} && git push ${args}` });

export const bash = ($: Engine, command: string) =>
  $.tool.call({ tool: "Bash", command });

export const record = ($: Engine, input: Record<string, unknown>) =>
  $.tool.call({
    tool: "mcp__claudetto__ai_policy",
    repo: "",
    verdict: "allowed",
    read: [],
    ...input,
  });

export const POLICY =
  // biome-ignore lint/plugin: test input data
  "Contributions made with an LLM are not accepted in this project.";

/** A world with one checkout of `owner/name` in `/work/<name>` and the policy file `AGENTS.md`. */
export const world = (name: string, owner = "them", text = POLICY): World => ({
  files: { [`/work/${name}/AGENTS.md`]: text, [`/work/${name}/src/a.ts`]: "" },
  repos: {
    [`/work/${name}`]: [
      `/work/${name}`,
      `https://github.com/${owner}/${name}.git`,
    ],
  },
});

/** Starts a test in a repository (the first push asks for the verdict) `them/<name>` with a `forbidden` verdict. `cwd` is the session folder, `/work/<name>` by default. */
export const close = async ($: Engine, on: On, name: string, cwd?: string) => {
  const w = world(name);
  if (cwd !== undefined) w.cwd = cwd;
  const disk = stub(on, w);
  await push($, `/work/${name}`);
  await record($, {
    repo: `github.com/them/${name}`,
    verdict: "forbidden",
    quote: POLICY,
    read: [`/work/${name}/AGENTS.md`],
  });
  return disk;
};
